# region: sift
def sift(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: digest
def digest(xs, floor_=2):
    return [v for v in xs if v >= floor_]

# region: fold
def fold(xs):
    return [v for v in xs if v % 2 == 0]

# region: emit
def emit(xs):
    return [v * v for v in xs[1:]]

# region: shape
def shape(xs, cut=5):
    lo = [v for v in xs if v < cut]
    hi = [v for v in xs if v >= cut]
    return {'n': len(xs), 'lo': len(lo), 'hi': len(hi)}

# region: gather
def gather(summary, name='gamma'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return gather(shape(emit(fold(digest(sift(raw))))))

